swift - <<'SWIFT'
import ApplicationServices
import Foundation

let systemWide = AXUIElementCreateSystemWide()
var focusedApp: AnyObject?
let err = AXUIElementCopyAttributeValue(systemWide, kAXFocusedApplicationAttribute as CFString, &focusedApp)
print("focusedAppErr", err.rawValue)
if let app = focusedApp {
    let appEl = app as! AXUIElement
    var windows: CFTypeRef?
    let e2 = AXUIElementCopyAttributeValue(appEl, kAXWindowsAttribute as CFString, &windows)
    print("windowsErr", e2.rawValue)
    if let arr = windows as? [AXUIElement] {
        for win in arr {
            var title: CFTypeRef?
            AXUIElementCopyAttributeValue(win, kAXTitleAttribute as CFString, &title)
            print("window", title ?? "nil")
            var buttons: CFTypeRef?
            let e3 = AXUIElementCopyAttributeValue(win, kAXChildrenAttribute as CFString, &buttons)
            print("childrenErr", e3.rawValue)
            if let children = buttons as? [AXUIElement] {
                for child in children {
                    var role: CFTypeRef?
                    AXUIElementCopyAttributeValue(child, kAXRoleAttribute as CFString, &role)
                    var label: CFTypeRef?
                    AXUIElementCopyAttributeValue(child, kAXTitleAttribute as CFString, &label)
                    print("child", role ?? "nil", label ?? "nil")
                }
            }
        }
    }
}
SWIFT
